#[test]
fn finds_key() {
    let items = vec![Setting { key: String::from("host"), val: String::from("localhost") }];
    let res: Option<&str> = find_setting(&items, "host");
    assert_eq!(res, Some("localhost"));
}

#[test]
fn missing_key() {
    let items = vec![Setting { key: String::from("host"), val: String::from("localhost") }];
    let res: Option<&str> = find_setting(&items, "port");
    assert_eq!(res, None);
}
